def is_valid_json(text):
    try:
        json.loads(text)
        return True
    except:
        return False

def generate_dataset(output_dir="data/json_instruct", eval_size=100, retries=3):
    os.makedirs(output_dir, exist_ok=True)
    examples = []
    with open("prompts/teacher_json_prompt.txt") as f:
        prompt_template = f.read()

    print(f"Generating {len(TASKS)} examples using teacher model...\n")
    for task in tqdm(TASKS):
        input_section = f"Input: {task['input']}" if task.get("input") else ""
        prompt = prompt_template.format(
            instruction=task["instruction"],
            input_section=input_section
        )
        success = False
        for attempt in range(retries):
            try:
                try:
                    response = call_model(prompt, role="teacher", temperature=0.1)
                except Exception:
                    print(f"  Teacher unavailable, using fallback...")
                    response = call_model(prompt, role="fallback", temperature=0.1)
                if is_valid_json(response):
                    examples.append({
                        "instruction": task["instruction"],
                        "input": task.get("input", ""),
                        "output": response,
                        "task_type": task["type"]
                    })
                    success = True
                    break
                else:
                    print(f"  Invalid JSON on attempt {attempt+1}, retrying...")
            except Exception as e:
                print(f"  Error: {e}")
        if not success:
            print(f"  Skipped after {retries} attempts")

    random.shuffle(examples)
    eval_data = examples[:eval_size]
    train_data = examples[eval_size:]
    with open(f"{output_dir}/train.json", "w") as f:
        json.dump(train_data, f, indent=2)
    with open(f"{output_dir}/eval.json", "w") as f:
        json.dump(eval_data, f, indent=2)
    print(f"\nDone! {len(train_data)} train, {len(eval_data)} eval")

if __name__ == "__main__":
    generate_dataset()
